import { NextRequest, NextResponse } from 'next/server';
import crypto from 'crypto';

const WEBHOOK_SECRET = process.env.WEBHOOK_SIGNING_SECRET;

export async function POST(req: NextRequest): Promise<NextResponse> {
  if (!WEBHOOK_SECRET) {
    return NextResponse.json({ error: 'Server misconfiguration: secret missing' }, { status: 500 });
  }

  const signature = req.headers.get('x-webhook-signature');
  if (!signature) {
    return NextResponse.json({ error: 'Missing webhook signature header' }, { status: 401 });
  }

  try {
    const rawBody = await req.text();
    const expectedSignature = crypto
      .createHmac('sha256', WEBHOOK_SECRET)
      .update(rawBody)
      .digest('hex');

    const isAuthentic = crypto.timingSafeEqual(
      Buffer.from(signature, 'hex'),
      Buffer.from(expectedSignature, 'hex')
    );

    if (!isAuthentic) {
      return NextResponse.json({ error: 'Invalid webhook signature' }, { status: 403 });
    }

    const payload = JSON.parse(rawBody);
    // Process validated webhook payload here
    return NextResponse.json({ received: true, eventId: payload.id }, { status: 200 });
  } catch (error) {
    return NextResponse.json({ error: 'Malformed payload or server error' }, { status: 400 });
  }
}
